//! Survey profiles of the surveyed endpoint references.
//!
//! Points are `(station, elevation)` binary64 bits with the bed at elevation 0.
//! `cap` holds the maximum stage bits, equal to the cap depth.

// Generated by `transcribe.py` in `resource/evidence/surveyed-endpoints/` from its
// frozen `reference.json`. Regenerate instead of editing.

#[derive(Clone, Copy, Debug)]
pub struct Profile {
    pub name: &'static str,
    pub points: &'static [[u64; 2]],
    pub cap: u64,
    /// Band knot depths in metres, bed and cap included.
    pub knots: &'static [f64],
}

/// `rectangle-3`: (-1.5, 4), (-1.5, 0), (1.5, 0), (1.5, 4).
pub const RECTANGLE_3: Profile = Profile {
    name: "rectangle-3",
    points: &[
        [0xbff8000000000000, 0x4010000000000000],
        [0xbff8000000000000, 0x0000000000000000],
        [0x3ff8000000000000, 0x0000000000000000],
        [0x3ff8000000000000, 0x4010000000000000],
    ],
    cap: 0x4010000000000000,
    knots: &[0.0, 4.0],
};

